mapper.select:
select la.id, la.phone, la.name, la.identification_number, la.start_date, la.end_date, la.total_amount, la.status, la.source_type, la.additional_info, ai.id store_id, ai.name store_name, ai.district_id, ai.district_name, ai.city_id, ai.city_name, ai.province_id, ai.province_name, ri.id seat_id, ri.seat_code, pt.id payment_type_id, pt.name payment_type_name, pt.pay_month_count, lt.id booking_term_id, lt.month_count, lt.unit from booking_order la left join study_store ai on la.store_id = ai.id and ai.is_deleted=0 left join seat ri on la.seat_id = ri.id and ri.is_deleted=0 left join payment_type pt on la.payment_type_id = pt.id and pt.is_deleted=0 left join booking_term lt on la.booking_term_id = lt.id and lt.is_deleted=0
la.is_deleted = 0
and ai.province_id = #{queryVo.provinceId}
and ai.city_id = #{queryVo.cityId}
and ai.district_id = #{queryVo.districtId}
and la.store_id = #{queryVo.storeId}
and ri.seat_code like concat('%',#{queryVo.seatCode},'%')
and la.name like concat('%',#{queryVo.name},'%')
and la.phone like concat('%',#{queryVo.phone},'%')
and la.status = #{queryVo.status}

select count(1)
from booking_order bo
where bo.is_deleted = 0
  and bo.seat_id = #{seatId}
  and bo.status in (1, 2, 5, 7, 8)
  and bo.start_date < #{endDate}
  and bo.end_date > #{startDate}

    and bo.id != #{excludeId}
